/**
 * Narrow the deck to the decades and genres the players picked at setup.
 * An empty (or omitted) list means "no filter on this axis" — that is what the
 * setup screen sends when every chip is deselected, and players expect that to
 * mean "everything", not "nothing".
 * @param {readonly Card[]} deck
 * @param {{decades?: readonly number[], genres?: readonly string[]}} [filters]
 * @returns {Card[]}
 */
export function filterDeck(deck, { decades = [], genres = [] } = {}) {
  const wantDecade = new Set(decades);
  const wantGenre = new Set(genres);
  return deck.filter(
    (c) => (wantDecade.size === 0 || wantDecade.has(c.decade))
      && (wantGenre.size === 0 || wantGenre.has(c.genre)),
  );
}
